#!/usr/bin/env python3
"""Very weak UCI engine: always plays first legal move, and reports a large negative
score for White, making the python driver think White is lost.
"""
import sys
import chess

board = chess.Board()

def send(msg):
    print(msg)
    sys.stdout.flush()

def parse_position(cmd):
    global board
    tokens = cmd.split()
    if tokens[1] == 'startpos':
        board = chess.Board()
        moves = tokens[3:] if len(tokens) > 3 else []
    elif tokens[1] == 'fen':
        fen = ' '.join(tokens[2:8])
        board = chess.Board(fen)
        moves_index = 8
        moves = tokens[moves_index+1:] if len(tokens) > moves_index+1 else []
    else:
        return
    for mv in moves:
        board.push(chess.Move.from_uci(mv))

def pick_move():
    global board
    for mv in board.legal_moves:
        return mv
    return None

while True:
    line = sys.stdin.readline()
    if not line:
        break
    line = line.strip()
    if line == 'uci':
        send('id name DummyNegativeEngine')
        send('id author ChatGPT')
        send('uciok')
    elif line == 'isready':
        send('readyok')
    elif line.startswith('setoption'):
        # ignore all options
        pass
    elif line == 'ucinewgame':
        board = chess.Board()
    elif line.startswith('position'):
        parse_position(line)
    elif line.startswith('go'):
        # Always claim a huge advantage for Black (negative centipawns for White)
        send('info score cp -1000')
        mv = pick_move()
        if mv is None:
            send('bestmove 0000')
        else:
            send(f'bestmove {mv.uci()}')
    elif line == 'quit':
        break
    # ignore other commands
PY"}
